namespace Fanex.BetList.Core.UnitTest.Builder.ChoiceBuilder
{
    using Fanex.BetList.Core.Builder.ChoiceBuilder;
    using Fanex.BetList.Core.UnitTest.Common.Templates;
    using Fanex.BetList.Core.UnitTest.Common.Enums;
    using NUnit.Framework;

    public class Choice1103Test
    {
        private ChoiceCreator _choiceCreator;

        [SetUp]
        public void Setup()
        {
            _choiceCreator = new ChoiceCreator(new Choice1103(), BetTypes.Sicbo);
        }

        [Test]
        public void Ticket_ShowLeagueLeagueNameIsLiveBaccaratWithShowTime()
        {
            // Act
            string actualHtml = _choiceCreator.GetOuterHtml(XPathChoice.LeagueName);

            // Assert
            string expectedHtml = string.Format(TemplateChoice.LaagueLeagueName, "Live Baccarat&nbsp;" + _choiceCreator.Ticket.ShowTime);
            Assert.AreEqual(expectedHtml, actualHtml);
        }
    }
}